L[81]=[
  ("पाठ-81 («पहला आर्क जलाना छड़») का सार क्या है?","पहला आर्क अनुशासन की परीक्षा है, जोश की नहीं","वेल्डिंग का आर्क हाथ के पास जलता छोटा सूरज है","टूटना-चिपकना नए का पहला संघर्ष है — हार नहीं","एंगल और चैनल वेल्डिंग के काम की असली रीढ़ हैं"),
  ("«पहला आर्क जलाना छड़» (पाठ-81) की आम ग़लती क्या है?","\"बस एक नज़र देखने भर को\" बिना हेलमेट आर्क जलाना — पाठ-1 की क़सम पहले ही दिन तोड़ना; आर्क की एक झलक भी आँख जला देती है","पाइपों की अदला-बदली करना: कभी भी लाल पाइप को ऑक्सीजन में या नीले पाइप को ईंधन गैस में जोड़ने की ज़बरदस्ती कोशिश न करें","चिपकने की शर्म में अभ्यास घटा देना — यह मोड़ हर उस्ताद के रास्ते में आया था; शर्म नहीं, गिनती रखिए और गिरते अंक देखिए","दूसरे का हेलमेट बिना पट्टा कसे पहनना — ढीला हेलमेट टाँके के बीच सरकता है, और आदमी नंगी आँख से आर्क में झाँक बैठता है"),
  ("कौन-सी ग़लती «छड़ छुआना और उठाना» वाले पाठ-81 में बताई गई?","पहले ही दिन लकीर-टाँके की होड़ — सीढ़ी का पहला डंडा छोड़ने वाला मुँह के बल गिरता है","सिर्फ़ लिखावट पर भरोसा — लिखावट हर भाषा में नहीं होती; रंग-आकार हर भाषा में होते हैं","\"आग लगी तो देख लेंगे।\" — बिना पास रखी बाल्टी के \"देख लेना\" सिर्फ़ जलता हुआ देखना है","काम के हिसाब से गलत मशीन चुनना: बिना सोचे-समझे बहुत भारी या बहुत हल्की मशीन ले लेना"),
  ("«पहला आर्क जलाना» (पाठ-81) की सावधानी क्या है?","अभ्यास-ठिये पर हिस्सा-1 के पूरे नियम — पानी-बाल्टी पास, घेरा साफ़, हवादार जगह (पाठ-5/8/16)","अगले हिस्से (यंत्रों की पहचान) में हम मशीन के और पास जाएँगे — पुर्ज़े, बटन, छड़ें, सेटिंग","पेंट छीलने का काम हमेशा खुली हवा में या पंखे के सामने करें ताकि धूल और धुआँ आपसे दूर उड़े","सीमा-रेखा पहचानें: इस पाठ में हमने केवल बाहरी केबल, होल्डर और क्लैंप की मरम्मत सीखी है"),
  ("तेज़-दोहराव: पाठ-81 («पहला आर्क जलाना») का एक सूत्र?","रस्म की चार चौकियाँ: वर्दी","काम के अनुसार सही रूप चुनें","कमज़ोरी ज़ंग, कवच रंग-रोगन","हरा/हरा-पीला तार = अर्थिंग"),
]
L[82]=[
  ("पाठ-82 («आर्क टूटना चिपकना नए») का सार क्या है?","टूटना-चिपकना नए का पहला संघर्ष है — हार नहीं","वेल्डिंग का आर्क हाथ के पास जलता छोटा सूरज है","पहला आर्क अनुशासन की परीक्षा है, जोश की नहीं","एंगल और चैनल वेल्डिंग के काम की असली रीढ़ हैं"),
  ("«आर्क टूटना चिपकना नए» (पाठ-82) की आम ग़लती क्या है?","चिपकी छड़ को पूरे बदन के ज़ोर से उखाड़ना — टुकड़ा उछलता है, हाथ फिसलता है, कभी-कभी क्लैंप समेत सब गिरता है","\"पंखा चला दिया, हो गया।\" — दुकान के भीतर घुमाया गया पंखा धुआँ बाहर नहीं फेंकता, पूरी दुकान में बाँट देता है","तीन-लकीर परीक्षा में चाल-कोण भी बदल देना — तब सबक़ गड्ड-मड्ड हो जाता है; एक बार में एक ही घुंडी की परीक्षा","तेल या ग्रीस की बोतल को खुला छोड़ना: पेटी में रखे तेल या ग्रीस की शीशी का ढक्कन ढीला होने से वह बह सकता है"),
  ("कौन-सी ग़लती «नए का पहला संघर्ष» वाले पाठ-82 में बताई गई?","चिपकने की शर्म में अभ्यास घटा देना — यह मोड़ हर उस्ताद के रास्ते में आया था; शर्म नहीं, गिनती रखिए और गिरते अंक देखिए","दूसरे का हेलमेट बिना पट्टा कसे पहनना — ढीला हेलमेट टाँके के बीच सरकता है, और आदमी नंगी आँख से आर्क में झाँक बैठता है","चिह्न को सजावट समझना — कारख़ाने की दीवार पर एक भी चीज़ सजावट नहीं; हर बोर्ड किसी पुरानी दुर्घटना की क़ीमत पर टँगा है","पड़ोसी के मीटर या घरेलू लाइन से जुगाड़-कनेक्शन जोड़ना: बहुत से लोग सोचते हैं कि ऐसा करके वे बिजली का बिल बचा रहे हैं"),
  ("«आर्क टूटना चिपकना» (पाठ-82) की सावधानी क्या है?","चिपककर छूटी छड़ का सिरा तपा हुआ है — ज़मीन पर सोच कर रखिए (पाठ-8), पैर के पास कभी नहीं","अगले हिस्से (यंत्रों की पहचान) में हम मशीन के और पास जाएँगे — पुर्ज़े, बटन, छड़ें, सेटिंग","सीमा-रेखा पहचानें: इस पाठ में हमने केवल बाहरी केबल, होल्डर और क्लैंप की मरम्मत सीखी है","जब भी एल्युमिनियम को घिसा जाता है, तो उसका बहुत महीन चूरा (Fine Dust) हवा में उड़ता है"),
  ("तेज़-दोहराव: पाठ-82 («आर्क टूटना चिपकना») का एक सूत्र?","चिपके: मरोड़ो → जबड़ा खोलो → मशीन बंद","क्रम: सफ़ाई → दबाओ → टैक → सिलो → पलटो","\"आदत\" दिमाग़ को पड़ती है, कान को नहीं","साबुत ढँकाव (नंगा तांबा = नंगी बिजली)"),
]
L[83]=[
  ("पाठ-83 («सीधी लकीर का टाँका») का सार क्या है?","सीधी लकीर वेल्डर की वर्णमाला का पहला अक्षर है, और उसकी कॉपी की लाइन चॉक-रेखा","होल्डर दिन भर हथेली में रहने वाला चिमटा है — बिजली और आपके बीच की आख़िरी दीवार","धातु और वेल्डिंग छड़ की सही जोड़ी बनाना वेल्डिंग की सबसे बुनियादी जरूरत है","घटिया या नक़ली लोहा कारीगर की साख और ग्राहक की जान दोनों के लिए ख़तरनाक है"),
  ("«सीधी लकीर का टाँका» (पाठ-83) की आम ग़लती क्या है?","पहले ही दिन लंबी लकीर का लोभ — छोटे टुकड़ों की सीधी माला लंबी घसीट से हज़ार गुना बेहतर","चालू मशीन में होल्डर यूँ ही फेंक देना — जहाँ छुएगा, वहीं चिंगारी; ठिकाना = सूखी खूँटी","उतरते-उतरते लाइन लंबी खींचते जाना — टुकड़ों-साँस का नियम (पाठ-94) खड़ी में भी उतना ही","गरम लोहे को नापकर काटना: वेल्डिंग के तुरंत बाद गर्म पाइप को नापकर अगला टुकड़ा न काटें"),
  ("कौन-सी ग़लती «का टाँका पहला अभ्यास» वाले पाठ-83 में बताई गई?","बिना रेखा के अभ्यास — नज़र को ठिकाना ही नहीं दिया","फफोला फोड़ना — क़ुदरत की पट्टी फाड़कर ज़ख़्म खोलना","तराशकर सफ़ाई भूल जाना — घाटी का कचरा सीधा जड़ में","टैक पर रुक जाना या कूद जाना — ढेर या कच्ची साँधें"),
  ("«सीधी लकीर का» (पाठ-83) की सावधानी क्या है?","अभ्यास की मस्ती में वर्दी ढीली नहीं — हिस्सा-1 की क़सम रोज़ की है, पहले दिन की नहीं","कतरन का कोना कोई साधारण कोना नहीं है, वह नुकीले और धारदार टुकड़ों का एक छोटा जंगल है","तेल और ग्रीस से कट्टर दुश्मनी: यह गैस वेल्डिंग का सबसे बड़ा और सबसे ख़तरनाक नियम है","किनारा-कटना ज़िम्मेदार जोड़ (झूला, रेलिंग, सीढ़ी, भार-ढाँचा) पर दिखे तो टालना नहीं"),
  ("तेज़-दोहराव: पाठ-83 («सीधी लकीर का») का एक सूत्र?","रेखा खींचो — बिना लीक की बैलगाड़ी नहीं","वेल्डिंग करते समय कभी भी घुंडी न घुमाएँ","क्रम: सफ़ाई → दबाओ → टैक → सिलो → पलटो","कतरन बेचकर बही में एंट्री करना न भूलें"),
]
L[84]=[
  ("पाठ-84 («टाँके की चाल गति») का सार क्या है?","हाथ की चाल वेल्डर की दूसरी घुंडी है","चाप की बोली वेल्डर की तीसरी आँख है","वेल्डिंग मशीनों के दो परिवार हैं","अच्छा जोड़ टाँके से पहले बनता है"),
  ("«टाँके की चाल गति» (पाठ-84) की आम ग़लती क्या है?","चाल को सेकंड-गिनती से बाँधने की ज़िद — \"तीन गिनकर आगे\" वाला हाथ तालाब अंधा हो जाता है; गिनती नहीं, तालाब","चाय-गुटखे से थकान \"भगाना\" — ये काँटा छिपाते हैं, बैटरी नहीं चढ़ाते; ऊपर से गुटखा अपना अलग क़र्ज़ लिखता है","जोड़ाई छिपाने को उस पर मोटा ढेर चढ़ा देना — गाँठ ढँकती नहीं, बड़ी होती है; इलाज रीत में है, ढेर में नहीं","नीचे बच्चों/राहगीरों का खड़े रहना — काम रोककर पहले घेरा; ऊपर से बरसती चिंगारी के नीचे तमाशबीन नहीं चाहिए"),
  ("कौन-सी ग़लती «चाल गति का खेल» वाले पाठ-84 में बताई गई?","तेज़-सुथरे दिखते टाँके पर इतराना — मीठा धोखा; किनारों का मिलन और जड़ देखिए","मोटी पेंसिल या स्केच पेन का उपयोग: मोटी लकीर वेल्डिंग में भ्रम पैदा करती है","\"झटका छोटा था, ठीक हूँ\" — बिजली का हिसाब भीतर चलता है; जाँच हर झटके के बाद","कान में रुई ठूँसना — रुई धूल की ढाल है, शोर की नहीं; ऊपर से झूठा भरोसा अलग"),
  ("«टाँके की चाल» (पाठ-84) की सावधानी क्या है?","तेज़ चाल के लोभ में जड़-कच्चा टाँका ज़िम्मेदार काम","• प्लग बाहर निकालें: मशीन के बाहरी हिस्सों की सफ़ाई","दोनों परिवारों पर हिस्सा-1 के सारे नियम बराबर लागू","झिरी वाले जोड़ के आर-पार नीचे चिंगारी-टपकन गिरती है"),
  ("तेज़-दोहराव: पाठ-84 («टाँके की चाल») का एक सूत्र?","चाल = दूसरी घुंडी, कलाई वाली","काम के अनुसार सही रूप चुनें","चिंगारी 10 मीटर तक उड़ती है","इलाज: तिरछे किनारे = V-घाटी"),
]
L[85]=[
  ("पाठ-85 («छड़ का झुकाव कोण») का सार क्या है?","छड़ का झुकाव तिकड़ी की तीसरी घुंडी है","रोशनी और हवा काम की जगह की दो साँसें हैं","हाथ की चाल वेल्डर की दूसरी घुंडी है","चाप की बोली वेल्डर की तीसरी आँख है"),
  ("«छड़ का झुकाव कोण» (पाठ-85) की आम ग़लती क्या है?","कोण को चाँदा-नाप से रटने की ज़िद — नाप समझ के लिए है, हाथ आदत से सधता है","आवाज़ को \"बस अंदाज़े की चीज़\" समझना — यह अंदाज़ा नहीं, उसी पल की गवाही है","चिपकने पर ज़ोर-आज़माइश — कल का पाठ आने से पहले घबराइए मत, मशीन बंद कीजिए","\"धातु ही तो है\" कहकर आम छड़ से हाथ डाल देना — हैंडल वाली कहानी याद रखिए"),
  ("कौन-सी ग़लती «झुकाव कोण की समझ» वाले पाठ-85 में बताई गई?","चाल-कोण उल्टी दिशा में झुकाना — छड़ आगे की ओर लेटे तो तालाब आगे भागकर आर्क के नीचे आ जाता है","गलत जगह गलत पाइप चुनना: सीढ़ी की पकड़-पट्टी में चौकोर पाइप लगा देना, जिससे हाथ में कोने चुभें","नाप बताते समय मोटाई भूल जाना: अक्सर नए कारीगर सिर्फ़ \"25×25 का एंगल दे दो\" कहकर रुक जाते हैं","सारे औज़ारों को एक ही बोरे में भर देना: बोरा पेटी नहीं है! बोरे में औज़ार आपस में टकराते हैं"),
  ("«छड़ का झुकाव» (पाठ-85) की सावधानी क्या है?","सूखा-रियाज़ भी होल्डर में छड़ लगाकर हो तो मशीन बंद और प्लग बाहर (पाठ-6)","1. गरम इंजन पर डीज़ल कभी न डालें: जनरेटर चलते-चलते बहुत गरम हो जाता है","तांबे-पीतल की घिसाई का महीन चूरा भी साँस का माल नहीं — मास्क (पाठ-7)","तिरछी घिसाई में ग्राइंडर के फिसलने का ढंग सीधी घिसाई से अलग होता है"),
  ("तेज़-दोहराव: पाठ-85 («छड़ का झुकाव») का एक सूत्र?","चाल-कोण = क़लम-सा झुकाव (75-80 के आस-पास), टाँके की ओर","पहचान: सलेटी रंग + चुंबक ज़ोर से + पीली फुलझड़ी-चिंगारी","ज़्यादा = चौड़ा-चपटा, किनारा-कटना, बौछार, पतले में छेद","ज़ंग की घिसाई करते समय सुरक्षा चश्मा और मास्क अनिवार्य"),
]
L[86]=[
  ("पाठ-86 («करंट का सही अंक») का सार क्या है?","टाँका अपनी सूरत में करंट की कहानी लिखता है — सही करंट की मोतियों-लड़ी जिसके किनारे धातु में घुले-मिले","बिजली गोल घेरे में चलती है — मशीन से होल्डर-छड़ के रास्ते काम तक, और काम से अर्थ-क्लैंप के रास्ते वापस","इस पाठ में हमने सीखा कि एक पेशेवर वेल्डर की असली पहचान उसकी व्यवस्थित औज़ार-पेटी (Toolbox) से होती है","दुर्घटना का आधा हिस्सा मशीन से नहीं, बिखरी जगह से आता है — इसलिए वेल्डर की दुकान रसोई की तरह सजती है"),
  ("«करंट का सही अंक» (पाठ-86) की आम ग़लती क्या है?","हर रोग की एक दवा — घुंडी: करंट बढ़ाना-घटाना आधे रोगों का परदा है, इलाज नहीं","\"टंकी को पानी से धो लिया, अब ठीक है।\" — एक बार धोने से भीतर की भाप नहीं मरती","मोटी पेंसिल या स्केच पेन का उपयोग: मोटी लकीर वेल्डिंग में भ्रम पैदा करती है","नाक से सूँघकर रिसाव ढूँढना: कई लोग सोचते हैं कि गैस लीक होगी तो महक आ जाएगी"),
  ("कौन-सी ग़लती «ज़्यादा कम की पहचान» वाले पाठ-86 में बताई गई?","ऊँचे-चढ़े टाँके को \"मोटा है, मज़बूत होगा\" कहना — अनमिले किनारे वाला ढेर टिका है, जुड़ा नहीं","सुर याद किए बिना सिर्फ़ नाम रटना — सुर कान से बैठता है, कॉपी से नहीं; असली चाप ज़रूर सुनिए","पतले लोहे पर बहुत मोटी छड़ चलाना: इससे लोहा तुरंत कटकर बह जाता है और काम ख़राब हो जाता है","एक ही पर्ची थमाना — विकल्प के बिना ग्राहक फ़ैसले का साथी नहीं, सिर्फ़ भुगतानकर्ता रहता है"),
  ("«करंट का सही» (पाठ-86) की सावधानी क्या है?","किनारा-कटना ज़िम्मेदार जोड़ (झूला, रेलिंग, सीढ़ी, भार-ढाँचा) पर दिखे तो टालना नहीं","अभ्यास की मस्ती में वर्दी ढीली नहीं — हिस्सा-1 की क़सम रोज़ की है, पहले दिन की नहीं","अर्थिंग और सुरक्षा लाइन (Earthing Safety): किराए पर ली गई कोई भी बिजली की मशीन हो","तेल और ग्रीस से कट्टर दुश्मनी: यह गैस वेल्डिंग का सबसे बड़ा और सबसे ख़तरनाक नियम है"),
  ("तेज़-दोहराव: पाठ-86 («करंट का सही») का एक सूत्र?","सही = बराबर लड़ी, घुले-मिले किनारे, गिनती के छींटे","चुनाव के तीन सवाल — काम कहाँ? बिजली कैसी? हाथ कैसे?","रिसाव-जाँच सिर्फ़ साबुन-पानी से, माचिस से कभी नहीं","घरेलू कनेक्शन पर धंधा करना ग़ैर-क़ानूनी और ख़तरनाक"),
]
L[87]=[
  ("पाठ-87 («टाँके की आवाज़ कान») का सार क्या है?","चाप की बोली वेल्डर की तीसरी आँख है","हाथ की चाल वेल्डर की दूसरी घुंडी है","वेल्डिंग मशीनों के दो परिवार हैं","अच्छा जोड़ टाँके से पहले बनता है"),
  ("«टाँके की आवाज़ कान» (पाठ-87) की आम ग़लती क्या है?","शोर-भरी दुकान में आवाज़-जाँच छोड़ देना — शोर ही है तो बग़ल का ग्राइंडर दो सेकंड रुकवाना सस्ता है, ख़राब जोड़ महँगा","पूरी खेप को एक-सा मान लेना — डीलर अक्सर ऊपर की दो डंडियाँ असली ब्रांड की रखते हैं और नीचे घटिया माल छुपा देते हैं","गलत पोलैरिटी (Polarity) चुनना: अगर डीसी (DC) वेल्डिंग करते समय आपने टॉर्च को प्लस (+) वाले टर्मिनल में जोड़ दिया","ख़राबी मिलने पर \"चला लेंगे\" — जाँच का पूरा मतलब ही तब है जब ख़राबी पर काम रुके; वरना जाँच रस्म है, सुरक्षा नहीं"),
  ("कौन-सी ग़लती «आवाज़ कान से जाँच» वाले पाठ-87 में बताई गई?","हिचकी सुनकर भी \"लकीर पूरी कर लूँ\" — जीवित-जाँच की पूरी क़ीमत रुकने में है","\"झटका छोटा था, ठीक हूँ\" — बिजली का हिसाब भीतर चलता है; जाँच हर झटके के बाद","जाँच सिर्फ़ काम के अंत में करना — तब सुधार का दाम दस गुना हो चुका होता है","गाँठ को अंत समझना — गाँठ माला को बिखरने से रोकती है; पहनना रोज़ का काम है"),
  ("«टाँके की आवाज़» (पाठ-87) की सावधानी क्या है?","कान-रक्षा (पाठ-12) से समझौता कभी नहीं — और यह उल्टी समझ निकाल दीजिए कि \"सुनने के लिए रक्षक उतारना पड़ेगा\": अच्छा कान-रक्षक","प्लग बाहर निकालना: जब भी ग्राइंडर का पहिया बदलना हो या कोई मरम्मत करनी हो, तो सबसे पहले प्लग को बिजली के बोर्ड से बाहर खींचें","घटिया निकला माल कभी भी ऐसे कामों में इस्तेमाल न करें जहाँ जान का जोखिम हो (जैसे झूला, सीढ़ी, छत की रेलिंग, या भारी छज्जा)","सरिये का बँधा लच्छा-बंडल खोलते समय सिरे कमानी की तरह झटके से उछलते हैं — चेहरा हटाकर, दस्ताने पहनकर, बंधन आख़िर में काटिए"),
  ("तेज़-दोहराव: पाठ-87 («टाँके की आवाज़») का एक सूत्र?","चटचट (तड़के-सी, एक-सी) = सही","चोट = पाठ-10, हर महीने दोहराव","सुरक्षा सामान हमेशा सबसे ऊपर","फ़ैसला माल करता है, जोश नहीं"),
]
L[88]=[
  ("पाठ-88 («बट जोड़ आमने सामने») का सार क्या है?","बट जोड़ — दो किनारे आमने-सामने, एक सीध में — जोड़-परिवार का पहला और सबसे खरा सदस्य है","अपनी पहली वेल्डिंग मशीन ख़रीदना हर नए कारीगर के जीवन का एक बड़ा मील का पत्थर होता है","हाथ आग के सबसे पास और पैर गिरते अंगारों के रास्ते में — इसलिए दोनों की ढाल चमड़े की","सारे नियमों के बाद भी चोट कभी-कभार लगती है, और तब पहले 5 मिनट की समझ ही असली दवा है"),
  ("«बट जोड़ आमने सामने» (पाठ-88) की आम ग़लती क्या है?","टुकड़े कसकर भिड़ाना — \"सटे = जुड़े\" वाली उल्टी सहज-बुद्धि","आँख से मोटाई का दावा — रंगी-चढ़ी चादर आँख को मोटी दिखती है","कच्चा-ठंडा टैक — हिलाते ही खुले तो वह खूँटा नहीं, धोखा है","धूप के तपे माल पर सीधी नाप-टाँका — पाठ-29/62 की सीख भूलना"),
  ("कौन-सी ग़लती «आमने सामने का जोड़» वाले पाठ-88 में बताई गई?","झिरी ज़रूरत से बड़ी कर देना — बड़ा फ़ासला पतले माल में सीधे नीचे टपकता है (छेद-कथा पाठ-100 की)","टैक के बाद गुनिया छोड़ देना — टैक की गरमी भी खड़े को खींचती है; तीन-बार-गुनिया का नियम बिना छूट","काले चश्मे में चिपिंग करना: वेल्डिंग हेलमेट या काले चश्मे को पहनकर चिपिंग करने की कोशिश न करें","टाँका चढ़ाई के बीचों-बीच ऊपर की सतह पर चला देना — सिलाई किनारे की रेखा पर होती है, पीठ पर नहीं"),
  ("«बट जोड़ आमने» (पाठ-88) की सावधानी क्या है?","झिरी वाले जोड़ के आर-पार नीचे चिंगारी-टपकन गिरती है","पहला इलाज इलाज की जगह नहीं लेता — वह डॉक्टर तक का पुल है","• प्लग बाहर निकालें: मशीन के बाहरी हिस्सों की सफ़ाई","बल्ब, पंखा और उनके तार चिंगारी-क्षेत्र से ऊपर व दूर"),
  ("तेज़-दोहराव: पाठ-88 («बट जोड़ आमने») का एक सूत्र?","बट = आमने-सामने, एक सीध, एक बनकर","स्क्राइबर = बारीक और सटीक खरोंच","चुंबक का हल्का चिपकना या फिसलना","कपड़ों में आग: रुको-गिरो-लुढ़को"),
]
L[89]=[
  ("पाठ-89 («लैप जोड़ चढ़ा हुआ») का सार क्या है?","लैप जोड़ — एक टुकड़ा दूसरे पर उँगली-भर चढ़ा — पतली चादरों का घर-जमाई है: नीचे वाला टुकड़ा ख़ुद सहारा बनता है और झिरी-नाप का झंझट","इस पाठ में हमने सीखा कि वेल्डिंग मशीन की उम्र बढ़ाने के लिए बहुत बड़े ख़र्च की नहीं, बल्कि छोटी और नियमित देखभाल की ज़रूरत होती है","वेल्डिंग का बारीक धुआँ लगभग अदृश्य है, पर साँस के साथ फेफड़ों की गहराई तक उतरता है — एक दिन में सिरदर्द, सालों में पक्का नुक़सान","इस पाठ में हमने सीखा कि वेल्डिंग केबल, होल्डर और अर्थ-क्लैंप वेल्डिंग मशीन के सबसे संवेदनशील बाहरी हिस्से हैं जो रोज़ घिसते हैं"),
  ("«लैप जोड़ चढ़ा हुआ» (पाठ-89) की आम ग़लती क्या है?","नाम-मात्र की चढ़ाई — किनारे-किनारे टिका जोड़","पहली ग़लती: बिना सोचे-समझे मशीन का ढक्कन खोलना","ठहराव गिनती से नापना — धड़कन तालाब की झलक से","टैक की पपड़ी समेत भराई चढ़ाना — कचरे की गिरह"),
  ("कौन-सी ग़लती «जोड़ चढ़ा हुआ जोड़» वाले पाठ-89 में बताई गई?","कोण ऊपर के पतले किनारे की ओर झुकाना — किनारा गलकर पीछे भागता है (पाठ-92 में यह रोग चरम पर मिलेगा)","ऊपर से झाँककर \"हवा ठीक है\" मान लेना — भारी गैस दिखती नहीं; परख दीये/हवा-इंतज़ाम की है, आँख की नहीं","टाँका बिगड़ते ही मशीन खोलना/मिस्त्री दौड़ना — पहले चालीस सेकंड की क्लैंप-जाँच; आधी बीमारी वहीं है","\"काम तो चल ही जाएगा\" सोचकर समझौता करना: वेल्डिंग में बहुत तेज़ बिजली और गर्मी का इस्तेमाल होता है"),
  ("«लैप जोड़ चढ़ा» (पाठ-89) की सावधानी क्या है?","चादरों को क्लैंप से दबाते समय उँगलियाँ जबड़े की सीध से बाहर (पाठ-24), और पतले माल की सिलाई में पाठ-71 का पूरा क़ायदा","तपे काम पर पानी डालना जोड़ के भीतर छिपा तनाव भरता है — यह टेढ़ेपन से भी बुरा सौदा है, क्योंकि दरार बिना बताए आती है","तप्त टुकड़े का ख़तरा: कटाई पूरी होने के बाद जो टुकड़ा कटकर अलग गिरता है, वह बहुत देर तक अत्यधिक तप्त (Hot) रहता है","पैने किनारे: जब भी कास्ट आयरन का कोई टूटा पुर्ज़ा आपके पास आए, तो उसके किनारे बहुत पैने और काँच जैसे तीखे होते हैं"),
  ("तेज़-दोहराव: पाठ-89 («लैप जोड़ चढ़ा») का एक सूत्र?","लैप = चढ़ा हुआ, खपरैल-सा — पतली चादर का घर-जमाई","गाड़ी पर माल लादने से पहले फीते और गेज से जाँचें","अर्थ-क्लैंप को हमेशा ज़ंग और कालिख से साफ़ रखें","पिट-पिट-सन्नाटा = कम करंट/दबा फ़ासला/कच्चा अर्थ"),
]
L[90]=[
  ("पाठ-90 («टी जोड़ खड़ा मिलन») का सार क्या है?","टी-जोड़ — एक लेटा, एक खड़ा — ढाँचे-रैक-फ्रेम की आधी दुनिया का आधार है","गाँव-देहात की वेल्डिंग में जनरेटर एक बेहद ज़रूरी लेकिन नखरेबाज़ साथी है","टैक पकड़ के छोटे टाँके हैं — नींव के खूँटे: मटर-दाने भर के, पर सच्चे","किनारे का जोड़ परिवार का शांत बंदी-कारीगर है — दो टुकड़े बग़ल-बग़ल"),
  ("«टी जोड़ खड़ा मिलन» (पाठ-90) की आम ग़लती क्या है?","कोण खड़े की ओर झुकाना — पतले खड़े का पेट कटना टी की सबसे महँगी चोट है","नोक नीचे की ओर झुकाना — धक्का माल को और नीचे धकेलता है, दौड़ वहीं हारी","कठिन दिशा को बहादुरी का तमग़ा समझना — ग्राहक लड़ी देखता है, दिशा नहीं","मुंडेर पर मोटी छड़-भारी करंट — दो नंगे किनारे पल में गलकर ढह जाते हैं"),
  ("कौन-सी ग़लती «टी जोड़ खड़ा मिलन» वाले पाठ-90 में बताई गई?","ज़िम्मेदार टी एक तरफ़ सिलना — एक कब्ज़े वाला दरवाज़ा","मैल-ज़ंग के ऊपर टाँका — चमक हफ़्ते की, उखड़ना पक्का","ऊँच-नीच किनारों पर सीधी सिलाई — ऊँचा जला, नीचा कोरा","फ़ीते के हुक को हथौड़ी से ठोकना: यह सबसे आम गलती है"),
  ("«टी जोड़ खड़ा» (पाठ-90) की सावधानी क्या है?","खड़े टुकड़े को हाथ से थामकर टैक कभी नहीं — गुनिया-टेक या क्लैंप थामे, हाथ दूर (पाठ-24): टैक का छींटा थामती उँगलियों पर ही गिरता है","चमकती जस्ता चढ़ी चादर के अलावा भी — रंग चढ़े या तेल-ग्रीस लगे लोहे की वेल्डिंग का धुआँ ज़्यादा कड़वा और ज़्यादा नुक़सानदेह होता है","अर्थिंग पहरेदार है, छूट नहीं — अर्थिंग जुड़ी होने पर भी पाठ-6 के तीनों नियम (सूखा हाथ, सूखी ज़मीन, साबुत तार) पूरे पहरे पर रहेंगे","घिसाई-खुरचाई का हर काम चश्मा-मास्क-दस्ताने माँगता है (हिस्सा-1 का पूरा कुनबा) — उड़ता ज़ंग-चूरा आँख और साँस दोनों का दुश्मन है"),
  ("तेज़-दोहराव: पाठ-90 («टी जोड़ खड़ा») का एक सूत्र?","टी = लेटा + खड़ा — ढाँचों का कमाऊ जोड़","वेल्डिंग करते समय कभी भी घुंडी न घुमाएँ","क्रम: सफ़ाई → दबाओ → टैक → सिलो → पलटो","कतरन बेचकर बही में एंट्री करना न भूलें"),
]
L[91]=[
  ("पाठ-91 («कोने का जोड़») का सार क्या है?","कोने का जोड़ हर चौकोर चीज़ के चारों सिरों की रीढ़ है","अर्थिंग यानी ज़मीन का तीसरा तार दुकान का चुप पहरेदार है","कारख़ाने की दीवारें चार रंगों की भाषा में बोलती हैं","एक बेहतरीन वेल्डर अपनी मशीन का खुद डॉक्टर होता है"),
  ("«कोने का जोड़» (पाठ-91) की आम ग़लती क्या है?","कोना हाथ में झुलाकर टैक करना — तीन हाथों का काम दो से; कोना-टेक बनाइए","जंग-रंग-तेल के ऊपर क्लैंप — छुआ है, जुड़ा नहीं; पहले रेती की दो रगड़","ऊपर का मोती देखकर जोड़ पास कर देना — पीठ पलटे बिना बट का हिसाब अधूरा","\"अच्छी वाली देना\" कहकर ख़रीद — अच्छे का कोई गेज नहीं होता, अंक बोलिए"),
  ("कौन-सी ग़लती «कोने का जोड़» वाले पाठ-91 में बताई गई?","चारों गुनिया देखकर विकर्ण छोड़ना — चार सच्चे कोने, एक झूठी चौखट","माल आगे भागने पर चाल धीमी कर देना — उलटी दवा: यहाँ तेज़ी ही इलाज","चटका शीशा टेप से चलाना — दरार से किरण रिसती है; टेप ढाल नहीं है","टेढ़ी होती लकीर को \"पूरी तो कर लूँ\" कहकर घसीटना — ग़लती की बुआई"),
  ("पाठ-91 «कोने का जोड़» — सावधानियाँ क्या कहती हैं?","कोने की भराई में गरमी दो दीवारों के बीच घिरती है","होल्डर की हर जाँच-मरम्मत मशीन बंद, प्लग बाहर करके","चढ़ती लकीर में चेहरा तालाब के नीचे-सामने रहता है","तेज़ चाल के लोभ में जड़-कच्चा टाँका ज़िम्मेदार काम"),
  ("«कोने का जोड़» (पाठ-91) — दोहराव में क्या है?","कोना = किनारे-से-किनारे, 90 की क़सम","ढीला जोड़ = गरमी और बिजली की बर्बादी","धारदार औज़ारों की नोक हमेशा ढकी रहे","कम करंट = ठंडा टाँका, छड़ का चिपकना"),
]
L[92]=[
  ("«किनारे का जोड़» (पाठ-92) की मुख्य बात?","किनारे का जोड़ परिवार का शांत बंदी-कारीगर है — दो टुकड़े बग़ल-बग़ल","ज़ंग लोहे का एक ऐसा रोग है जो नमी और हवा के मिलने से पैदा होता है","रंगे लोहे पर वेल्डिंग करना जोड़ और सेहत दोनों के लिए ख़तरनाक है","ओवरहेड सीढ़ी की चोटी है — गुरुत्व पूरा दुश्मन, हर बूँद आपकी ओर"),
  ("पाठ-92 «किनारे का जोड़» में आम ग़लती?","मुंडेर पर मोटी छड़-भारी करंट — दो नंगे किनारे पल में गलकर ढह जाते हैं","नोक नीचे की ओर झुकाना — धक्का माल को और नीचे धकेलता है, दौड़ वहीं हारी","कठिन दिशा को बहादुरी का तमग़ा समझना — ग्राहक लड़ी देखता है, दिशा नहीं","\"शोर की आदत पड़ गई है।\" — आदत दिमाग़ को पड़ी है; कान का घिसना जारी है"),
  ("कौन-सी ग़लती «किनारे का जोड़» वाले पाठ-92 में बताई गई?","किनारे के जोड़ पर भार-भरोसा — कुंडा, हुक, टँगाई: सीमा-निषेध की सीधी अवहेलना","\"टंकी को पानी से धो लिया, अब ठीक है।\" — एक बार धोने से भीतर की भाप नहीं मरती","मोटी पेंसिल या स्केच पेन का उपयोग: मोटी लकीर वेल्डिंग में भ्रम पैदा करती है","नाक से सूँघकर रिसाव ढूँढना: कई लोग सोचते हैं कि गैस लीक होगी तो महक आ जाएगी"),
  ("सावधानी — पाठ-92 («किनारे का जोड़»)?","खड़े किनारों की मुंडेर छाती-आँख की सीध में आती है — छींटे सीधे ऊपर उछलते हैं: हेलमेट नीचे, गला-कवच ठीक (पाठ-3)","मीटर का लोड बढ़वाना हो, कनेक्शन की श्रेणी (घरेलू से व्यावसायिक) बदलवानी हो, या मीटर ख़राब होने की शिकायत करनी हो","वज़न-गणित औज़ार है, हथियार नहीं — दूसरे कारीगर का भेद ग्राहक के सामने खोलते समय ज़बान नपी रखिए: अपना हिसाब दिखाइए","तप्त टुकड़े का ख़तरा: कटाई पूरी होने के बाद जो टुकड़ा कटकर अलग गिरता है, वह बहुत देर तक अत्यधिक तप्त (Hot) रहता है"),
  ("तेज़-दोहराव: पाठ-92 («किनारे का जोड़») का एक सूत्र?","किनारे का जोड़ = बग़ल-बग़ल सटे, टाँका साझी मुंडेर पर","चुनाव के तीन सवाल — काम कहाँ? बिजली कैसी? हाथ कैसे?","एसिटिलीन सिलेंडर = लाल/मैरून, उलटी चूड़ी (नट पर कट)","नमी और ज़ंग से बचाव = ज़मीन से ऊपर सूखी जगह पर रखना"),
]
L[93]=[
  ("पाठ-93 («टैक वेल्डिंग पकड़ के») का सार क्या है?","टैक पकड़ के छोटे टाँके हैं — नींव के खूँटे: मटर-दाने भर के, पर सच्चे","टी-जोड़ — एक लेटा, एक खड़ा — ढाँचे-रैक-फ्रेम की आधी दुनिया का आधार है","किनारे का जोड़ परिवार का शांत बंदी-कारीगर है — दो टुकड़े बग़ल-बग़ल","वेल्डर की कमर उसकी आधी पूँजी है, और ग़लत उठान उसका सबसे चुप दुश्मन"),
  ("«टैक वेल्डिंग पकड़ के» (पाठ-93) की आम ग़लती क्या है?","टैक को भराई-सा लंबा खींच देना — बड़ा टैक गाँठ भी है, खिंचाव भी","चटका शीशा टेप से चलाना — दरार से किरण रिसती है; टेप ढाल नहीं है","एड़ी छोड़े बिना धार तक तराश देना — पहली परत नीचे से बह जाती है","पर्ची ज़बानी बनाना — बोला हुआ हिसाब हवा है, लिखा हुआ दस्तावेज़"),
  ("कौन-सी ग़लती «पकड़ के छोटे टाँके» वाले पाठ-93 में बताई गई?","एक ही ओर लगातार टैक — खिंचाव की बुआई भराई से पहले ही","सफ़ाई सिर्फ़ ऊपर वाली सतह की — मिलन दोनों सतहों का है","कतरन को कचरा समझना: इसके टुकड़े बहुत क़ीमती होते हैं","ज़िम्मेदार टी एक तरफ़ सिलना — एक कब्ज़े वाला दरवाज़ा"),
  ("«टैक वेल्डिंग पकड़» (पाठ-93) की सावधानी क्या है?","टैक तोड़ते समय छेनी की चोट से धातु-कण उछलते हैं — चश्मा अनिवार्य (पाठ-27), और चोट की दिशा अपने व साथी के बदन से हटाकर","चादरों को क्लैंप से दबाते समय उँगलियाँ जबड़े की सीध से बाहर (पाठ-24), और पतले माल की सिलाई में पाठ-71 का पूरा क़ायदा","तपे काम पर पानी डालना जोड़ के भीतर छिपा तनाव भरता है — यह टेढ़ेपन से भी बुरा सौदा है, क्योंकि दरार बिना बताए आती है","तप्त टुकड़े का ख़तरा: कटाई पूरी होने के बाद जो टुकड़ा कटकर अलग गिरता है, वह बहुत देर तक अत्यधिक तप्त (Hot) रहता है"),
  ("तेज़-दोहराव: पाठ-93 («टैक वेल्डिंग पकड़») का एक सूत्र?","टैक = मटर-दाने भर का सच्चा खूँटा — छोटा पर पक्का","लेटी छड़ = छींटे-बिखरी छतरी; खड़ी = बेक़ाबू तालाब","गाड़ी पर माल लादने से पहले फीते और गेज से जाँचें","जंग/रंग/तेल = बिजली के रोड़े — पहले रेती की रगड़"),
]
L[94]=[
  ("पाठ-94 («पूरी लाइन भरना टैक») का सार क्या है?","पूरी लाइन की भराई टुकड़ों में बनती है पर लड़ी दिखनी चाहिए — यही पके हाथ की पहचान है","अपनी पहली वेल्डिंग मशीन ख़रीदना हर नए कारीगर के जीवन का एक बड़ा मील का पत्थर होता है","हाथ आग के सबसे पास और पैर गिरते अंगारों के रास्ते में — इसलिए दोनों की ढाल चमड़े की","सारे नियमों के बाद भी चोट कभी-कभार लगती है, और तब पहले 5 मिनट की समझ ही असली दवा है"),
  ("«पूरी लाइन भरना टैक» (पाठ-94) की आम ग़लती क्या है?","पूरी लाइन एक साँस में — महानियम की सीधी अवहेलना (टेढ़ापन + थकान)","थके हाथ से \"बस यह जोड़ और\" — इस दिशा में थकान की क़ीमत सबसे महँगी","माल आगे भागने पर चाल धीमी कर देना — उलटी दवा: यहाँ तेज़ी ही इलाज","टाँका ग़ौर से देखने के लिए धारा के ठीक ऊपर झुकना — सबसे आम ग़लती"),
  ("कौन-सी ग़लती «टैक से पक्के तक» वाले पाठ-94 में बताई गई?","टैक पर रुक जाना या कूद जाना — ढेर या कच्ची साँधें","दूसरी ग़लती: ज़ंग लगे लोहे पर ही क्लैंप ठोक देना","साफ़ करके काम कल पर टालना — कल तक धातु फिर मैली","पहली ग़लती: बिना सोचे-समझे मशीन का ढक्कन खोलना"),
  ("«पूरी लाइन भरना» (पाठ-94) की सावधानी क्या है?","लंबी भराई लंबा तपाती है — टुकड़ों के बीच की साँस में पट्टी-क्लैंप की गरमी जाँचिए, पलटना-छूना दस्ताने से","ईमानदार स्व-परीक्षा: जब आप नीचे दी गई परीक्षा या AI की परीक्षा हल करें, तो पीछे के पाठ खोलकर नक़ल न करें","खाने-दवा-बच्चों से छूने वाले काम में धातु-दर्जे पर मोल-भाव पूरी तरह बंद — वहाँ सस्ती पर्ची बनती ही नहीं","कड़ी रोशनी से आँखों का बचाव: टीआईजी (TIG) की आर्क से निकलने वाली पराबैंगनी किरणें बहुत ही तीखी होती हैं"),
  ("तेज़-दोहराव: पाठ-94 («पूरी लाइन भरना») का एक सूत्र?","टुकड़े बालिश्त-भर, क्रम आर-पार, हर टुकड़े पर साँस","सही = बराबर लड़ी, घुले-मिले किनारे, गिनती के छींटे","लेटी छड़ = छींटे-बिखरी छतरी; खड़ी = बेक़ाबू तालाब","मशीन अच्छी-बुरी नहीं — रास्ते से मेल खाती या नहीं"),
]
L[95]=[
  ("पाठ-95 («समतल स्थिति फ्लैट सबसे») का सार क्या है?","टाँका चार दिशाओं में लगता है — समतल, आड़ी, खड़ी, सिर-ऊपर","तांबा और पीतल लोहे के कुनबे से बाहर के दो रंगीन पड़ोसी हैं","अर्थिंग यानी ज़मीन का तीसरा तार दुकान का चुप पहरेदार है","सरिया ग्रिल-दुनिया की जान है, पर दो जातियों में बँटा है"),
  ("«समतल स्थिति फ्लैट सबसे» (पाठ-95) की आम ग़लती क्या है?","कठिन दिशा को बहादुरी का तमग़ा समझना — ग्राहक लड़ी देखता है, दिशा नहीं","जंग-रंग-तेल के ऊपर क्लैंप — छुआ है, जुड़ा नहीं; पहले रेती की दो रगड़","ऊपर का मोती देखकर जोड़ पास कर देना — पीठ पलटे बिना बट का हिसाब अधूरा","\"अच्छी वाली देना\" कहकर ख़रीद — अच्छे का कोई गेज नहीं होता, अंक बोलिए"),
  ("कौन-सी ग़लती «फ्लैट सबसे आसान दिशा» वाले पाठ-95 में बताई गई?","घुमाने का आलस — \"लिटाने में वक़्त लगेगा\" कहकर खड़े से लड़ना: लिटाने का वक़्त हमेशा झालर छीलने से सस्ता","अच्छे अंक पर माला छोड़ देना — ज्ञान का इम्तिहान आज हुआ; आदत का इम्तिहान बिजली, आग और थकान रोज़ लेते हैं","पतले सर्विस वायर (Service Wire) का उपयोग: लोड के हिसाब से तार पतला होने पर बिजली का बिल तो बढ़ता ही है","एसिटिलीन का दबाव 1.5 kg/cm² से ऊपर सेट करना: ज़्यादा प्रेशर से जल्दी काम होगा, इस लालच में कभी न पड़ें"),
  ("«समतल स्थिति फ्लैट» (पाठ-95) की सावधानी क्या है?","काम घुमाना-लिटाना ख़ुद एक काम है — भारी ढाँचा दो जन से, घोड़ियाँ-सहारे पहले जमाकर, उँगलियाँ किनारों की सीध से बाहर (पाठ-13/24)","अर्थिंग पहरेदार है, छूट नहीं — अर्थिंग जुड़ी होने पर भी पाठ-6 के तीनों नियम (सूखा हाथ, सूखी ज़मीन, साबुत तार) पूरे पहरे पर रहेंगे","घिसाई-खुरचाई का हर काम चश्मा-मास्क-दस्ताने माँगता है (हिस्सा-1 का पूरा कुनबा) — उड़ता ज़ंग-चूरा आँख और साँस दोनों का दुश्मन है","प्लग बाहर निकालना: जब भी ग्राइंडर का पहिया बदलना हो या कोई मरम्मत करनी हो, तो सबसे पहले प्लग को बिजली के बोर्ड से बाहर खींचें"),
  ("तेज़-दोहराव: पाठ-95 («समतल स्थिति फ्लैट») का एक सूत्र?","चार दिशाएँ: समतल → आड़ी → खड़ी → सिर-ऊपर — हर डंडे पर गुरुत्व बड़ा","वारंटी के दौरान ढक्कन खोलने से सील टूटती है और वारंटी ख़त्म होती है","हर जोड़ = टोल-नाका — कम, कसे, सही पुर्ज़े से; उमेठ+टेप स्थायी नहीं","मरम्मत के बाद जोड़ को छूकर गरमी टटोलें, गरम जोड़ यानी अधूरी मरम्मत"),
]
L[96]=[
  ("पाठ-96 («आड़ी स्थिति हॉरिज़ॉन्टल») का सार क्या है?","आड़ी स्थिति पहली चढ़ाई है — टाँका दीवार पर, तालाब ढालू छत पर, और गुरुत्व पहली बार सामने से","दुकान में बचे-कटे टुकड़ों को कबाड़ समझना एक आम कारीगर की भूल है, जबकि वे दबी हुई कमाई हैं","गैस वेल्डिंग में लौ को पहचानना और उसे नियंत्रित करना ही एक कुशल कारीगर की असली पहचान है","पायलट हज़ार उड़ानों के बाद भी सूची से जाँचता है, क्योंकि याददाश्त थकती है और सूची नहीं"),
  ("«आड़ी स्थिति हॉरिज़ॉन्टल» (पाठ-96) की आम ग़लती क्या है?","समतल के अंक-छड़-चाल सीधे दीवार पर — आधे रोग की जड़ यही घमंड","\"बाद में समेट लूँगा।\" — बाद कभी नहीं आता; अगला काम आ जाता है","तौल-मिलान कभी न करना — कच्ची तौल चुपचाप महीनों खाती रहती है","\"रात को हुई जलन का वेल्डिंग से क्या नाता?\" — यही तो धोखा है"),
  ("कौन-सी ग़लती «आड़ी स्थिति हॉरिज़ॉन्टल» वाले पाठ-96 में बताई गई?","ऊपर ताकती छड़ को बहुत ऊपर उठा देना — अब ऊपरी किनारा कटेगा; ढाल हल्की, पूरी करवट नहीं","चालू मशीन में होल्डर यूँ ही फेंक देना — जहाँ छुएगा, वहीं चिंगारी; ठिकाना = सूखी खूँटी","सिर्फ़ लिखावट पर भरोसा — लिखावट हर भाषा में नहीं होती; रंग-आकार हर भाषा में होते हैं","पतली चादरों पर इस्तेमाल: गैस कटिंग टॉर्च का उपयोग पतली चादरों पर करना एक बड़ी भूल है"),
  ("पाठ-96 «आड़ी स्थिति हॉरिज़ॉन्टल» — सावधानियाँ क्या कहती हैं?","दीवार का काम बदन की सीध में है — छींटे-चिंगारी अब सीने-बाँहों पर बरसते हैं और लटककर गिरा माल सीधा पैरों पर: चमड़े का पूरा कवच","घिसाई-खुरचाई का हर काम चश्मा-मास्क-दस्ताने माँगता है (हिस्सा-1 का पूरा कुनबा) — उड़ता ज़ंग-चूरा आँख और साँस दोनों का दुश्मन है","प्लग बाहर निकालना: जब भी ग्राइंडर का पहिया बदलना हो या कोई मरम्मत करनी हो, तो सबसे पहले प्लग को बिजली के बोर्ड से बाहर खींचें","काम घुमाना-लिटाना ख़ुद एक काम है — भारी ढाँचा दो जन से, घोड़ियाँ-सहारे पहले जमाकर, उँगलियाँ किनारों की सीध से बाहर (पाठ-13/24)"),
  ("«आड़ी स्थिति हॉरिज़ॉन्टल» (पाठ-96) — दोहराव में क्या है?","आड़ी = दीवार पर आड़ी रेखा; तालाब ढालू छत पर","खुरपी, रेगमाल और ग्राइंडर का इस्तेमाल करें","हर टुकड़ा गरम मानो — उठाना सिर्फ़ चिमटे से","कल से शुरू होगा असली काम — पहला आर्क जलाना"),
]
L[97]=[
  ("पाठ-97 («खड़ी स्थिति ऊपर से») का सार क्या है?","खड़ी रेखा के दो रास्ते हैं — आज का रास्ता ऊपर से नीचे उतरना: गुरुत्व के साथ की तेज़ चाल, पतला-चपटा साफ़ टाँका","इस पाठ में हमने सीखा कि ऑटो-डार्कनिंग हेलमेट हमारी आँखों की सुरक्षा के लिए एक बहुत ही आधुनिक और बेहतरीन ढाल है","कच्चा लोहा यानी कास्ट आयरन लोहे के परिवार का वह भारी और भंगुर सदस्य है जो मुड़ता नहीं, बल्कि सीधे टूट जाता है","गैस कटिंग टॉर्च वेल्डिंग की दुनिया का एक बहुत ही शक्तिशाली औज़ार है जो मोटे लोहे को बहुत आसानी से काट सकता है"),
  ("«खड़ी स्थिति ऊपर से» (पाठ-97) की आम ग़लती क्या है?","तेज़-सुंदर सूरत देखकर उतरती चाल को हर जगह चलाना — मोटे जोड़ पर यह सुंदर धोखा है","केबल को कसकर लपेटना: केबल को किसी खूँटी या मशीन के ऊपर ही बहुत कस-कसकर लपेट देना","3. 'पराया माल' समझकर बेरहमी से इस्तेमाल करना: मशीन को गीली मिट्टी में छोड़ देना","घुमाने-उतारने का सवाल पूछे बिना ओवरहेड चढ़ जाना — बहादुरी नहीं, नासमझी (पाठ-95)"),
  ("कौन-सी ग़लती «स्थिति ऊपर से नीचे» वाले पाठ-97 में बताई गई?","नोक नीचे की ओर झुकाना — धक्का माल को और नीचे धकेलता है, दौड़ वहीं हारी","\"धातु ही तो है\" कहकर आम छड़ से हाथ डाल देना — हैंडल वाली कहानी याद रखिए","\"झनझनाहट हल्की है, चलता है।\" — हल्की झनझनाहट बड़ी रिसन की पहली बूँद है","गेज और मिलीमीटर को आपस में मिला देना — दो भाषाएँ हैं, अनुवाद सोच-समझकर"),
  ("«खड़ी स्थिति ऊपर» (पाठ-97) की सावधानी क्या है?","उतरती लकीर में तपा माल और छींटे आपके हाथ के नीचे की ओर बहते हैं","सबसे बड़ी बात दोबारा — बंद पाइप-टंकी पर बिना खोले चाप कभी नहीं","धारदार औज़ारों की नोक ढककर रखें: जब भी आप पेटी में हाथ डालें","करंट की घुंडी प्लास्टिक की बनी होती है ताकि आपको करंट न लगे"),
  ("तेज़-दोहराव: पाठ-97 («खड़ी स्थिति ऊपर») का एक सूत्र?","खड़ी के दो रास्ते — आज उतरना: गुरुत्व के साथ, तेज़-पतला-साफ़","तिकड़ी-अदालत: करंट → चाल → कोण — तीनों जाँचे बिना फ़ैसला नहीं","घुंडी दाहिने घुमाने से दबाव बढ़ता है, बाएँ घुमाने से घटता है","दो पर्चियाँ, दोनों ईमानदार, लिखी हुई — ज़बान चुप, हिसाब मुखर"),
]
L[98]=[
  ("पाठ-98 («खड़ी स्थिति नीचे से») का सार क्या है?","नीचे से ऊपर की चढ़ाई ज़िम्मेदार खड़े जोड़ों की शाही सड़क है","नाम-पट्टी मशीन का आधार कार्ड है, और उसके तीन अंक पूरी कुंडली","तांबा और पीतल लोहे के कुनबे से बाहर के दो रंगीन पड़ोसी हैं","लोहा ख़रीदना वेल्डिंग के धंधे का सबसे महत्वपूर्ण हिस्सा है"),
  ("«खड़ी स्थिति नीचे से» (पाठ-98) की आम ग़लती क्या है?","चढ़ाई में उतरने वाली रफ़्तार — झालर-पर-झालर","टैक की पपड़ी समेत भराई चढ़ाना — कचरे की गिरह","\"मैं तो दूर खड़ा हूँ।\" — 10 मीटर तक असर है","नाम-मात्र की चढ़ाई — किनारे-किनारे टिका जोड़"),
  ("कौन-सी ग़लती «स्थिति नीचे से ऊपर» वाले पाठ-98 में बताई गई?","झूल को बालिश्त-भर का झूला बना देना — चौड़ा झूला बीच ठंडा, किनारे जले","\"गरमी बहुत है, बनियान में कर लेता हूँ।\" — किरण को मौसम से मतलब नहीं","\"थोड़ी देर का ही तो ग्राइंडर है।\" — बूँद भी थोड़ी देर की ही होती है","बिना बिल का माल लेना — 'सस्ता पड़ेगा' सोचकर बिना पर्ची के माल उठाना"),
  ("«खड़ी स्थिति नीचे» (पाठ-98) की सावधानी क्या है?","चढ़ती लकीर में चेहरा तालाब के नीचे-सामने रहता है","होल्डर की हर जाँच-मरम्मत मशीन बंद, प्लग बाहर करके","कोने की भराई में गरमी दो दीवारों के बीच घिरती है","तेज़ चाल के लोभ में जड़-कच्चा टाँका ज़िम्मेदार काम"),
  ("तेज़-दोहराव: पाठ-98 («खड़ी स्थिति नीचे») का एक सूत्र?","चढ़ाई = जड़ की शाही सड़क — धीमी गरमी गहरी बैठे","अर्थ-क्लैंप को हमेशा ज़ंग और कालिख से साफ़ रखें","होल्डर = बिजली और हथेली के बीच की आख़िरी दीवार","जोड़ाई: पीछे चढ़ो — पुराना सिरा पिघलाओ, तब आगे"),
]
L[99]=[
  ("पाठ-99 («सिर के ऊपर ओवरहेड») का सार क्या है?","ओवरहेड सीढ़ी की चोटी है — गुरुत्व पूरा दुश्मन, हर बूँद आपकी ओर","रंगे लोहे पर वेल्डिंग करना जोड़ और सेहत दोनों के लिए ख़तरनाक है","अट्ठाईस पाठों की धातु-विद्या तीन सवालों की छलनी में सिमटती है","इस पाठ में हमने सीखा कि हर औज़ार को ख़रीदना अक़्लमंदी नहीं है"),
  ("«सिर के ऊपर ओवरहेड» (पाठ-99) की आम ग़लती क्या है?","कवच में एक \"छोटी-सी\" गली — खुली जेब, मुड़ा पायँचा: बूँद दर्ज़ी है, ढूँढ लेगी","मोटी पेंसिल या स्केच पेन का उपयोग: मोटी लकीर वेल्डिंग में भ्रम पैदा करती है","नाक से सूँघकर रिसाव ढूँढना: कई लोग सोचते हैं कि गैस लीक होगी तो महक आ जाएगी","दीवार की मोटाई पूछे बिना दाम की तुलना: दो पाइप बाहर से एक जैसे दिख सकते हैं"),
  ("कौन-सी ग़लती «ओवरहेड सबसे कठिन दिशा» वाले पाठ-99 में बताई गई?","सिर टाँके की ठीक सीध के नीचे — सुंदर नज़ारे की ग़लत खिड़की","तौल-मिलान कभी न करना — कच्ची तौल चुपचाप महीनों खाती रहती है","आँख से मोटाई का दावा — रंगी-चढ़ी चादर आँख को मोटी दिखती है","खुले-बरसाती काम में एक-किनारा सिलाई — साल भर बाद फूला जोड़"),
  ("«सिर के ऊपर» (पाठ-99) की सावधानी क्या है?","यह पूरा पाठ ही सावधानी है — फिर भी तीन बातें दोहराव माँगती हैं: नीचे का घेरा हर टुकड़े से पहले दोबारा","खाने-दवा-बच्चों से छूने वाले काम में धातु-दर्जे पर मोल-भाव पूरी तरह बंद — वहाँ सस्ती पर्ची बनती ही नहीं","क्लैंप लगाने-हटाने और उसकी हर सफ़ाई-मरम्मत बंद मशीन पर — चालू घेरे का क्लैंप हटाना जोड़ पर चिंगारी है","तेल और ग्रीस से तौबा: ऑक्सीजन रेगुलेटर और उसके गेज पर कभी भी तेल, मोबिल ऑयल या ग्रीस नहीं लगना चाहिए"),
  ("तेज़-दोहराव: पाठ-99 («सिर के ऊपर») का एक सूत्र?","ओवरहेड = चौथी दिशा, गुरुत्व पूरा दुश्मन","चाल का संतुलन = न बहुत तेज़, न बहुत धीमे","वेल्डिंग करते समय कभी भी घुंडी न घुमाएँ","लंबाई काम से — हर मीटर किराया वसूलता है"),
]
L[100]=[
  ("«टाँका छेद से बचना» (पाठ-100) की मुख्य बात?","छेद की जड़ एक ही है — एक जगह जमा हो गई गरमी; और इलाज पाँच चालों की रीत: पतली छड़ व नीचे वाले सिरे का करंट","बिजली गोल घेरे में चलती है — मशीन से होल्डर-छड़ के रास्ते काम तक, और काम से अर्थ-क्लैंप के रास्ते वापस","गैस वेल्डिंग में रेगुलेटर और उसके दोनों गेज हमारी सुरक्षा और काम की सफ़ाई के लिए सबसे ज़रूरी औज़ार हैं","इस पाठ में हमने सीखा कि एक पेशेवर वेल्डर की असली पहचान उसकी व्यवस्थित औज़ार-पेटी (Toolbox) से होती है"),
  ("«पतली चादर का टाँका» (पाठ-100) की आम ग़लती क्या है?","मोटे माल का करंट-भरोसा चादर पर — एक सीढ़ी की भूल, दस की सज़ा","ज़ंग पर रंग फेरकर \"नया जैसा\" बेचना — वह मरम्मत नहीं, छलावा है","\"बाद में समेट लूँगा।\" — बाद कभी नहीं आता; अगला काम आ जाता है","बिना छीले वेल्डिंग करना — इससे न केवल ज़हरीला धुआँ निकलता है"),
  ("कौन-सी ग़लती «टाँका छेद से बचना» वाले पाठ-100 में बताई गई?","गरम छेद पर तुरंत भराई की ज़िद — छेद बड़ा","बीच में ठहरना — ढेर + कटे किनारे की जोड़ी","\"एक झलक से क्या होगा?\" — हर झलक जुड़ती है","नया टुकड़ा नई जगह से — मनकों की टूटी माला"),
  ("«पतली चादर का» (पाठ-100) की सावधानी क्या है?","पटरे को क्लैंप से दबाइए, हाथ से थामकर नहीं — वह गरमी चूसने वाला तकिया है, यानी ख़ुद तपता है: हटाते समय दस्ताना और सोच","माइल्ड स्टील नरम है, पर उसकी कटी हुई धार और किनारे उतने ही तीखे हैं — दस्ताने का नियम (पाठ-4) धातु देखकर ढीला नहीं पड़ता","टैक तोड़ते समय छेनी की चोट से धातु-कण उछलते हैं — चश्मा अनिवार्य (पाठ-27), और चोट की दिशा अपने व साथी के बदन से हटाकर","चादरों को क्लैंप से दबाते समय उँगलियाँ जबड़े की सीध से बाहर (पाठ-24), और पतले माल की सिलाई में पाठ-71 का पूरा क़ायदा"),
  ("तेज़-दोहराव: पाठ-100 («पतली चादर का») का एक सूत्र?","छेद की जड़ = एक जगह जमी गरमी","काम के अनुसार सही रूप चुनें","चिंगारी 10 मीटर तक उड़ती है","इलाज: तिरछे किनारे = V-घाटी"),
]
